"""Legacy-compatible MS/MS matching core for SphinGOlipID.

This module is derived from the uploaded notebook ``MS2 Match (1).ipynb``.
The fragment-generation and matching logic is intentionally kept close to the
notebook version. Only path handling, imports, and a few I/O-safety details are
projectized so the code can be reused from scripts, CLI, or a future GUI.
"""

from __future__ import annotations

import os
import re
from time import time

import numpy as np
import pandas as pd

# Runtime variables set by ms2_pipeline.py before each run.
folder = "./"
ms2_data = "actual_ms2.xlsx"
DB_data = "DB_sheet.xlsx"
target_df = pd.DataFrame()
MS1_DB_PATH = None
MIN_FRAGMENT_INTENSITY = 20
OH_dict = {'d': 2, '5': 2, 'ω': 2, 'm': 1, '6': 3, 't': 3, 'q': 4}
frag_id1 = []
frag_mz1 = []

def real_mz_func(data_list):
    # 生成目标母离子
    parent_ion_df = pd.DataFrame()
    for data_li in data_list:
        if 'target' in data_li:
            target = float(re.findall('target m/z,(.*), m/z', data_li)[0].strip())
            if target_df.query(f'下限<={target}<=上限').shape[0] >= 1:
                t_df = target_df.query(f'下限<={target}<=上限')

                idx = re.findall('index:(.*?)\\n', data_li)[0].strip()
                sstime = float(re.findall('scan start time,(.*?),', data_li)[0].strip())
                t_df.loc[:, '母离子m/z实际值'] = target
                t_df.loc[:, 'Scan Start Time'] = sstime
                t_df.loc[:, 'idx'] = idx
                parent_ion_df = pd.concat([parent_ion_df, t_df], ignore_index=True)
        else:
            pass
    parent_ion_df.to_excel(os.path.join(folder, '目标母离子.xlsx'), index=False)

    # 将txt文件转成dataframe
    base_df = pd.DataFrame()
    for data_li in data_list:
        if 'target' in data_li:
            target = float(re.findall('target m/z,(.*), m/z', data_li)[0].strip())
            if target_df.query(f'下限<={target}<=上限').shape[0] >= 1:
                idx = re.findall('index:(.*?)\\n', data_li)[0].strip()
                A = data_li.split("binaryDataArray:")[1:][0].split(
                    "binary: ")[1].split("\n")[0].split(" ")[1:][:-1]
                B = data_li.split("binaryDataArray:")[1:][1].split(
                    "binary: ")[1].split("\n")[0].split(" ")[1:][:-1]
                df = pd.DataFrame({'idx': idx, 'A': A, 'B': B})
                base_df = pd.concat([base_df, df], ignore_index=True)
    # 按照target化合物理论m/z分组，并将相同分子式的idx写到一起
    grouped = parent_ion_df.groupby('target')
    grouped_idx = parent_ion_df.groupby('target')['idx'].apply(list).reset_index()
    base_df["idx"] = base_df["idx"].astype(str)
    # 创建一个空字典，用于存储每个分子式对应的数据
    dataframes = {}
    for index, row in grouped_idx.iterrows():
        molecular_mz = row['target']
        idx_list = row['idx']
        # 找到base_df中对应分子式的数据
        molecular_data = base_df[base_df['idx'].isin(idx_list)]
        # 将数据存入新的dataframe中
        dataframes[molecular_mz] = molecular_data
    # 创建一个ExcelWriter对象
#    writer = pd.ExcelWriter('实际质谱数据.xlsx', engine='xlsxwriter')
    writer = pd.ExcelWriter(ms2_data, engine='openpyxl')

    # 遍历dataframes字典，将每个dataframe写入一个单独的工作表
    for key, value in dataframes.items():
        value.to_excel(writer, sheet_name=str(key), index=False)

    # 保存并关闭ExcelWriter对象
    writer.close()

