def GSL_fragments(input_str, location, M, name):
    glycan = {'-Fuc': 146.0579, '-Gal': 162.0528, '-Glc': 162.0528, '-Hex': 162.0528, '-GalNAc': 203.08,
              '-GlcNAc': 203.08, '': 0,
              '-KDN': 250.07, '-NeuGc': 307.09, '-NeuAc': 291.09}

    list = input_str.split(" ")
    sumvalues = 0
    for i in range(len(list)):
        key = name + ''.join([item for item in list[:i + 1]])
        sumvalues += glycan[list[i]]
        value = M - sumvalues
        key2 = key + '-H2O'
        value2 = value - 18.0106
        frag_id1.extend([key, key2])
        frag_mz1.extend([value, value2])
        if list[i] == '-NeuAc':
            frag_id1.extend(['NeuAc+H', 'NeuAc+H-H2O'])
            frag_mz1.extend([292.10, 274.09])

    if location != '':
        locations = [int(x) for x in location.split(",")]
        # print(locations)

        for y in locations:
            key = name + list[y]
            sumvalues = glycan[list[y]]
            for item in list[0:y - 1]:
                key += item
                sumvalues += glycan[item]
                value = M - sumvalues
                remarks = name + '支链上' + list[y] + '先断裂'
                key2 = key + '-H2O'
                value2 = value - 18.0106
                frag_id1.extend([key, key2])
                frag_mz1.extend([value, value2])


#                 frag_id.update([key,key2])
#                 frag_mz.update([value,value2])

