def OCer(C0, MH, CPD, RT, Ab):
    fatty_acyl = {'12:0':200.1770,'14:0': 228.2082, '16:0': 256.2394, '18:0': 284.2706, '20:0': 312.3018, '22:0': 340.333,
                  '23:0': 354.3486,
                  '24:0': 368.3642, '26:0': 396.3954, '28:0': 424.4266, '30:0': 452.4578}
    for fac in [16, 18]:
        foc = int(C0) - 18 - fac
        fo = str(foc) + ':0'
        fra = CPD + '-' + fo
        mz = MH - 18.0106 - fatty_acyl[fo]
        sonname = f'1-O-acetyl-Cer(d18:1/{fac}:0/{foc}'
        frag_id1.append(fra)
        frag_mz1.append(mz)
        data = {'id': frag_id1, 'mz': frag_mz1}
    df_list = pd.DataFrame(data)
    df_list['s'] = sonname
    df_list['total'] = CPD
    df_list['target'] = MH
    df_list['numDB'] = len(set(frag_mz1))
    df_list['RT'] = RT
    df_list['Abund'] = Ab
    df_list.to_csv(f'{folder}out_DB.csv', index=False, mode='a', header=False, encoding='utf-8')


def learn_fuc(classy, CPD, strue, MH, RT, Ab):
    # 定义一个正则表达式模式，用于匹配输入字符串中的特定模式
    N_OH = re.search(r'\((m|d|t|q)\d+:', CPD).group(1)
    C0 = re.search(r'[mdtq](\d+):', CPD).group(1)
    U0 = re.search(r':(\d+)', CPD).group(1)
    Head = re.search(r'^(.*?)(?=\()', CPD).group(1)
    match = re.search(r'\(2OH\)|\(dOH\)|\(OH\)|\(OHOH\)', CPD)
    tail = match.group() if match else ''
    num_OH = OH_dict[N_OH]
    for i in range(1, num_OH + 1):
        keyH = CPD + '-' + str(i) + 'H2O'
        valueH = MH - i * 18.0106
        #         frag_id.update(keyH)
        #         frag_mz.update([valueH])
        frag_id1.append(keyH)
        frag_mz1.append(valueH)
    if bool(re.match("^[a-zA-Z]", classy)):
        func = globals().get(classy)
        if func:
            func(MH, CPD)
    elif strue != '':
        GSL_fragments(strue, classy, MH, CPD)

    if classy in ['Gb3_So', 'Glu_So', 'S1P', 'Lyso_sulfo', 'Lyso_SM', 'So']:
        so_fuc(MH, CPD, RT, Ab)
    elif classy == 'O_FA_cer':
        OCer(C0, MH, CPD, RT, Ab)
    else:
        almost_fuc(N_OH, C0, U0, Head, tail, MH, CPD, RT, Ab)

def query(row, attr_array, attr_cols):
    index_val = row[0]
    A_val = row[1]
    B_val = row[2]
    query_result = attr_array[(attr_array[:, attr_cols.index('下限')] <= A_val) & (attr_array[:, attr_cols.index('上限')] >= A_val)]
    if query_result.size > 0:
        result = np.hstack((query_result, np.array([[index_val, A_val, B_val]] * query_result.shape[0])))
        return result
    return None


def process_sheet(sheet_name, dfa, dfb):
    """Match one measured MS/MS sheet against one theoretical-fragment sheet.

    Compared with the notebook version, this function only adds defensive
    numeric conversion. Agilent txt-derived values sometimes arrive as strings
    after the intermediate Excel round-trip; comparing strings with the
    intensity threshold can raise a TypeError.
    """
    dfs1 = dfa.parse(sheet_name)
    dfs1['A'] = pd.to_numeric(dfs1['A'], errors='coerce')
    dfs1['B'] = pd.to_numeric(dfs1['B'], errors='coerce')
    dfs1 = dfs1.dropna(subset=['A', 'B'])
    dfs1 = dfs1[dfs1['B'] >= MIN_FRAGMENT_INTENSITY]

    dfs2 = dfb.parse(sheet_name)
    if dfs1.empty or dfs2.empty:
        return

    attr_array = dfs2.to_numpy()
    attr_cols = dfs2.columns.tolist()
    data_array = dfs1[['idx', 'A', 'B']].to_numpy()
    results = []
    for row in data_array:
        result = query(row, attr_array, attr_cols)
        if result is not None:
            results.append(result)
    if results:
        results_array = np.vstack(results)
        df_results = pd.DataFrame(results_array, columns=attr_cols + ['index', 'A', 'B'])
        df_results = df_results.drop_duplicates()
        df_results.to_csv(f'{folder}out-query.csv', index=False, mode='a', header=False, encoding='utf-8')


def process_group(group):
    listA = group['relmz'].tolist()
    listB = group['intense'].tolist()
    listC = group['idf'].tolist()
    num_rel = len(listA)
    length = group['lenDB'].iloc[0]
    sorce = num_rel / length
#     result = pd.DataFrame({'annotation': group['anno'].iloc[0], 'listA': [listA], 'listB': [listB], 'sor': [sor]})
    result = pd.DataFrame({'注释': group['anno'].iloc[0], 'target': group['target'].iloc[0],'匹配度分数':[sorce.round(2)],'母离子':group['total'].iloc[0],
                           'RT':group['RT'].iloc[0],'Abund':group['Abund'].iloc[0],'实际mz': [listA], '强度': [listB], '碎片': [listC]})
    return result
